const $=id=>document.getElementById(id);let calls=[],followUps=[],editing=null,followUpMode='create',loading=false;
const callHeaders=['Date','Time','Call type','Lead phone number','Lead name','Duration','Result','Remarks','Recording','Edit'];
const followUpHeaders=['Customer','Phone','Scheduled','Reason','Agent','Attempts','Status','Last call','Actions'];
const statusFilters=['All','Today','Upcoming','Calling','Completed','No Answer','Failed','Cancelled'];
function setOptions(select,items){select.replaceChildren(...items.map(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;return option}))}
function cell(row,value,className=''){const td=document.createElement('td');td.textContent=value??'—';if(className)td.className=className;row.append(td);return td}
function button(label,action,kind='quiet'){const el=document.createElement('button');el.type='button';el.textContent=label;el.className=kind;el.onclick=action;return el}
function headers(values){$('tableHead').replaceChildren(...values.map(value=>{const th=document.createElement('th');th.textContent=value;return th}))}
function renderCalls(){headers(callHeaders);$('totalLabel').textContent='Total calls';$('answeredLabel').textContent='Answered';$('unansweredLabel').textContent='Not answered';$('total').textContent=calls.length;$('answered').textContent=calls.filter(c=>c.result==='Answered').length;$('unanswered').textContent=calls.filter(c=>c.result==='Not answered').length;
 const query=$('search').value.toLowerCase();const rows=calls.filter(c=>(!$('type').value||c.type===$('type').value)&&(!$('result').value||c.result===$('result').value)&&(c.name+' '+c.phone).toLowerCase().includes(query));$('calls').replaceChildren();
 for(const call of rows){const tr=document.createElement('tr'),date=new Date(call.date);for(const text of [date.toLocaleDateString(),date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'}),call.type+(call.source==='browser'?' · Website':''),call.phone||'—',call.name||'—',call.duration==null?'—':Math.floor(call.duration/60)+':'+String(call.duration%60).padStart(2,'0'),call.result,call.remarks||'—'])cell(tr,text);const recording=cell(tr,'');if(call.recordingId)recording.append(button('▶ Play',()=>openRecording(call)));else recording.textContent='Not available';const actions=cell(tr,'');actions.append(button('Edit',()=>openCallEdit(call)));$('calls').append(tr)}
 $('historyStatus').textContent=rows.length?`${rows.length} call${rows.length===1?'':'s'} shown`:(calls.length?'No calls match these filters.':'No calls recorded yet.');$('dashboardHelp').textContent='Times shown in your browser’s local timezone. Duration measures the connected voice session. Website demos appear with no phone number.';
}
function renderFollowUps(){headers(followUpHeaders);$('totalLabel').textContent='Scheduled';$('answeredLabel').textContent='Calling';$('unansweredLabel').textContent='Completed';$('total').textContent=followUps.filter(f=>['Scheduled','Retry Scheduled','Rescheduled'].includes(f.status)).length;$('answered').textContent=followUps.filter(f=>f.status==='Calling').length;$('unanswered').textContent=followUps.filter(f=>f.status==='Completed').length;const query=$('search').value.toLowerCase(),rows=followUps.filter(f=>(f.customerName+' '+f.phoneNumber).toLowerCase().includes(query));
 $('calls').replaceChildren();for(const item of rows){const tr=document.createElement('tr');cell(tr,item.customerName);cell(tr,item.phoneNumber);cell(tr,new Date(item.nextAttemptAt||item.scheduledAt).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}));cell(tr,item.reason);cell(tr,item.agentId);cell(tr,`${item.attemptCount}/${item.maxAttempts}`);cell(tr,item.status,'follow-up-status status-'+item.status.toLowerCase().replaceAll(' ','-'));cell(tr,item.lastCallStatus||'—');const actions=cell(tr,'','row-actions');if(!['Completed','Cancelled','Calling'].includes(item.status))actions.append(button('Call now',()=>act(item,'call_now')));if(!['Completed','Cancelled','Calling'].includes(item.status))actions.append(button('Edit',()=>openFollowUp(item,'edit')));if(!['Completed','Cancelled','Calling'].includes(item.status))actions.append(button('Reschedule',()=>openFollowUp(item,'reschedule')));if(!['Completed','Cancelled','Calling'].includes(item.status))actions.append(button('Cancel',()=>act(item,'cancel')));actions.append(button('Details',()=>showDetails(item)));$('calls').append(tr)}
 $('historyStatus').textContent=rows.length?`${rows.length} follow-up${rows.length===1?'':'s'} shown`:'No follow-ups match these filters.';$('dashboardHelp').textContent='Follow-up times are stored in UTC and shown in your browser timezone. Airtel calls with an uncertain final state are never retried automatically.';
}
function render(){if($('view').value==='followups')renderFollowUps();else renderCalls()}
function configureFilters(){const follow=$('view').value==='followups';$('type').hidden=follow;if(follow)setOptions($('result'),statusFilters.map(v=>[v,v]));else setOptions($('result'),[['','All results'],['Answered','Answered'],['Not answered','Not answered'],['Pending','Pending'],['Unconfirmed','Unconfirmed']]);$('result').value=follow?'All':'';$('result').setAttribute('aria-label',follow?'Follow-up status':'Call result');render()}
async function api(url,options){const r=await fetch(url,options);if(r.status===401){location.replace('login');throw Error('Please sign in.')}const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Request failed.');return data}
async function load(){if(loading)return;loading=true;$('refresh').disabled=true;try{const [callData,followData]=await Promise.all([api('api/call-history'),api('api/follow-ups?filter='+encodeURIComponent($('view').value==='followups'?$('result').value||'All':'All'))]);calls=callData.calls;followUps=followData.followUps;render()}catch(e){$('historyStatus').textContent=e.message||'Could not load the dashboard. Click Refresh to retry.'}finally{loading=false;$('refresh').disabled=false}}
function localParts(iso,zone){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return {date:`${parts.year}-${parts.month}-${parts.day}`,time:`${parts.hour}:${parts.minute}`}}
function defaultSchedule(){const date=new Date(Date.now()+3600000),pad=v=>String(v).padStart(2,'0');return {date:`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`,time:`${pad(date.getHours())}:${pad(date.getMinutes())}`}}
function openFollowUp(item=null,mode='create'){followUpMode=mode;editing=item?.id||null;const values=item?localParts(item.scheduledAt,item.timezone):defaultSchedule();$('followUpTitle').textContent=mode==='create'?'Schedule follow-up':mode==='reschedule'?'Reschedule follow-up':'Edit follow-up';$('followUpName').value=item?.customerName||'';$('followUpPhone').value=item?.phoneNumber||'';$('followUpDate').value=values.date;$('followUpTime').value=values.time;$('followUpTimezone').value=item?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Kolkata';$('followUpReason').value=item?.reason||'';$('followUpNotes').value=item?.notes||'';$('followUpAgent').value=item?.agentId||'current';$('followUpAttempts').value=item?.maxAttempts||3;$('followUpRetry').value=item?.retryIntervalMinutes||30;$('followUpStatus').textContent='';for(const id of ['followUpName','followUpPhone','followUpReason','followUpNotes','followUpAgent','followUpAttempts','followUpRetry'])$(id).disabled=mode==='reschedule';for(const id of ['followUpDate','followUpTime','followUpTimezone'])$(id).disabled=mode==='edit';$('followUpDialog').showModal()}
function followUpPayload(){return {customerName:$('followUpName').value,phoneNumber:$('followUpPhone').value,date:$('followUpDate').value,time:$('followUpTime').value,timezone:$('followUpTimezone').value,reason:$('followUpReason').value,notes:$('followUpNotes').value,agentId:$('followUpAgent').value,maxAttempts:Number($('followUpAttempts').value),retryIntervalMinutes:Number($('followUpRetry').value)}}
async function saveFollowUp(event){event.preventDefault();$('saveFollowUp').disabled=true;try{const payload=followUpPayload();if(followUpMode!=='create')payload.action=followUpMode;await api(followUpMode==='create'?'api/follow-ups':'api/follow-ups/'+editing,{method:followUpMode==='create'?'POST':'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('followUpDialog').close();$('view').value='followups';configureFilters();await load()}catch(e){$('followUpStatus').textContent=e.message}finally{$('saveFollowUp').disabled=false}}
async function act(item,action){if(action==='call_now'&&!confirm(`Call ${item.customerName} at ${item.phoneNumber} now through Airtel?`))return;if(action==='cancel'&&!confirm('Cancel this follow-up?'))return;try{await api('api/follow-ups/'+item.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});await load()}catch(e){$('historyStatus').textContent=e.message}}
function showDetails(item){const fields=[['Status',item.status],['Customer',item.customerName],['Phone',item.phoneNumber],['Scheduled',new Date(item.scheduledAt).toLocaleString()],['Timezone',item.timezone],['Reason',item.reason],['Notes',item.notes||'—'],['Attempts',`${item.attemptCount}/${item.maxAttempts}`],['Last result',item.lastCallStatus||'—'],['Summary',item.callSummary||item.failureReason||'—'],['Airtel request',item.airtelCallId||'—'],['Recording',item.recordingId||'—']];$('followUpDetailsList').replaceChildren(...fields.flatMap(([label,value])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;return[dt,dd]}));$('followUpDetails').showModal()}
function openImport(){$('followUpCsv').value='';$('importStatus').textContent='';$('importDialog').showModal()}
async function importFollowUps(event){event.preventDefault();const file=$('followUpCsv').files[0];if(!file)return;$('startImport').disabled=true;$('importStatus').textContent='Validating and scheduling…';try{const result=await api('api/follow-ups/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csv:await file.text()})});const errors=result.skipped.slice(0,5).map(item=>`Row ${item.row}: ${item.error}`).join(' ');$('importStatus').textContent=`${result.summary.imported} scheduled automatically; ${result.summary.skipped} skipped.${errors?' '+errors:''}`;if(result.summary.imported){$('view').value='followups';configureFilters();await load()}}catch(e){$('importStatus').textContent=e.message}finally{$('startImport').disabled=false}}
function downloadFollowUpSample(){const now=new Date(Date.now()+86400000),date=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,csv=`customer_name,phone_number,follow_up_date,follow_up_time,timezone,reason,notes,agent_id,max_attempts,retry_interval_minutes,source_ref\nRahul Sharma,+919876543210,${date},11:30,Asia/Kolkata,Discuss test drive,Interested in SUV,current,3,30,lead-1001\n`,url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download='follow-up-sample.csv';link.click();URL.revokeObjectURL(url)}
function openCallEdit(call){editing=call.id;$('remarks').value=call.remarks||'';$('editResult').value='';$('editStatus').textContent='';$('editDialog').showModal()}
function openRecording(call){$('recordingDetails').textContent=(call.name||call.phone)+' · '+new Date(call.date).toLocaleString();$('recordingStatus').textContent='';const audio=$('recordingAudio');audio.src='api/call-recording?id='+encodeURIComponent(call.id);$('recordingDialog').showModal();audio.play().catch(()=>{$('recordingStatus').textContent='Press play to listen.'})}
$('refresh').onclick=load;$('view').onchange=()=>{configureFilters();load()};$('search').addEventListener('input',render);$('type').addEventListener('input',render);$('result').addEventListener('input',()=>$('view').value==='followups'?load():render());$('scheduleFollowUp').onclick=()=>openFollowUp();$('cancelFollowUp').onclick=()=>$('followUpDialog').close();$('followUpForm').onsubmit=saveFollowUp;$('closeFollowUpDetails').onclick=()=>$('followUpDetails').close();$('importFollowUps').onclick=openImport;$('cancelImport').onclick=()=>$('importDialog').close();$('importForm').onsubmit=importFollowUps;$('downloadFollowUpSample').onclick=downloadFollowUpSample;
$('cancelEdit').onclick=()=>$('editDialog').close();$('editForm').onsubmit=async event=>{event.preventDefault();$('saveEdit').disabled=true;try{await api('api/call-history',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:editing,remarks:$('remarks').value,result:$('editResult').value})});$('editDialog').close();await load()}catch(e){$('editStatus').textContent=e.message}finally{$('saveEdit').disabled=false}};
$('closeRecording').onclick=()=>$('recordingDialog').close();$('recordingDialog').addEventListener('close',()=>{const audio=$('recordingAudio');audio.pause();audio.removeAttribute('src');audio.load()});$('recordingAudio').addEventListener('error',()=>{if($('recordingAudio').hasAttribute('src'))$('recordingStatus').textContent='Recording could not be loaded.'});window.addEventListener('pagehide',()=>$('recordingAudio').pause());
const sidebarLogout=$('logout');if(sidebarLogout)sidebarLogout.onclick=async()=>{sidebarLogout.disabled=true;try{await api('api/auth/logout',{method:'POST'});location.replace('login')}catch(e){$('logoutStatus').textContent=e.message;sidebarLogout.disabled=false}};fetch('api/auth/status',{cache:'no-store'}).then(r=>r.json()).then(d=>{if(d.authenticated)$('sidebarUsername').textContent=(d.username||'').toUpperCase()}).catch(()=>{});
configureFilters();load();setInterval(()=>{if(!document.hidden&&!document.querySelector('dialog[open]'))load()},15000);
